SELECT now() AS observed_at;
SELECT path,status_code,error_code,count(*) FROM api_request_logs WHERE created_at >= '2026-09-18T02:30:00.000Z' AND created_at < '2026-10-18T02:30:00.000Z' AND path IN ('/v1/whois','/v2/whois','/v1/whois/bulk') GROUP BY 1,2,3 ORDER BY count(*) DESC;
SELECT key,count(*) FROM api_request_logs CROSS JOIN LATERAL jsonb_object_keys(response_json::jsonb) AS key WHERE created_at >= '2026-09-18T02:30:00.000Z' AND created_at < '2026-10-18T02:30:00.000Z' AND path IN ('/v1/whois','/v2/whois') AND status_code=200 AND position(chr(92)||'u0000' in response_json)=0 GROUP BY key ORDER BY count(*) DESC;
SELECT response_json::jsonb->>'source' AS source,response_json::jsonb->>'registered' AS registered,response_json::jsonb->>'available' AS available,response_json::jsonb->>'relay_whois_used' AS relay_used,count(*) FROM api_request_logs WHERE created_at >= '2026-09-18T02:30:00.000Z' AND created_at < '2026-10-18T02:30:00.000Z' AND path IN ('/v1/whois','/v2/whois') AND status_code=200 AND position(chr(92)||'u0000' in response_json)=0 GROUP BY 1,2,3,4 ORDER BY count(*) DESC;
